16	package org.springframework.samples.petclinic.model;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	import java.time.LocalDate;
22	import java.time.Month;
23	import java.time.Period;
24	import java.util.Map;
25	
26	/**
27	 * Pure derivations of an {@link Owner}'s read-only attributes.
28	 *
29	 * <p>Each method computes one derived value from an owner's own field values and
30	 * nothing else, so the computations stay stateless and side-effect free. {@link Owner}
31	 * exposes these through thin {@code @Transient} getters that pass in the relevant
32	 * fields; keeping the arithmetic here rather than on the entity leaves {@code Owner}
33	 * to describe its persistent state and relationships while its growing family of
34	 * derived attributes lives together in one place.
35	 */
36	final class OwnerDerivations {
37	
38	    /** Fixed city-to-region table used to derive {@link #region}. */
39	    private static final Map<String, String> CITY_REGION = Map.of(
40	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
41	
42	    /** Region -> inclusive 4-digit postcode range {low, high} used to derive
43	     *  {@link #region} in preference to the city. */
44	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
45	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
46	
47	    /** Fixed region-to-timezone table (IANA names) used to derive {@link #timezone}. */
48	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
49	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
50	
51	    private OwnerDerivations() {
52	    }
53	
54	    /**
55	     * The owner's locality, i.e. the canonical region it belongs to. This is read
56	     * from the unified {@code memberId} identity: the region is the leading
57	     * {@code <REGION>} component of the assigned member id, i.e. the run of letters
58	     * before its two-digit fiscal-year segment (e.g. {@code NSW} for
59	     * {@code NSW279F86D0817}). Until an owner has been assigned a member id (for example
60	     * while its create request is still being validated) this falls back to the region
61	     * derived directly from its own fields (see {@link #region(String, String)}).
62	     *
63	     * @return the canonical region string, or {@code "UNKNOWN"}
64	     */
65	    static String locality(String memberId, String postcode, String city) {
66	        String assigned = memberIdRegion(memberId);
67	        if (assigned != null) {
68	            return assigned;
69	        }
70	        return region(postcode, city);
71	    }
72	
73	    /**
74	     * The region component encoded in an assigned {@code memberId}: its leading
75	     * {@code <REGION>} run of letters, which precedes the two-digit fiscal-year segment
76	     * (e.g. {@code NSW} for {@code NSW279F86D0817}), or {@code null} when no member id has
77	     * been assigned yet or it carries no leading region component. Reading the region back
78	     * out of the identifier lives here so {@link #locality(String, String, String)} stays a
79	     * thin read-then-fall-back and the one place that knows the identifier's shape is
80	     * isolated.
81	     *
82	     * @return the encoded region, or {@code null}
83	     */
84	    private static String memberIdRegion(String memberId) {
85	        if (memberId == null) {
86	            return null;
87	        }
88	        int i = 0;
89	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
90	            i++;
91	        }
92	        return i > 0 ? memberId.substring(0, i) : null;
93	    }
94	
95	    /**
96	     * The canonical region derived for an owner from its own fields. The postcode is
97	     * consulted first: when it is present and falls within a known region's inclusive
98	     * 4-digit range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD
99	     * 4000-4099}) that region is returned. Only when the postcode is absent or in no
100	     * known range does this fall back to the fixed city-to-region table
101	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}),
102	     * returning {@code "UNKNOWN"} when the city is not in the table either. This yields
103	     * the same region for the known cities while disambiguating cities that share a name
104	     * via their postcode.
105	     *
106	     * @return the canonical region string, or {@code "UNKNOWN"}
107	     */
108	    static String region(String postcode, String city) {
109	        String byPostcode = regionForPostcode(postcode);
110	        if (byPostcode != null) {
111	            return byPostcode;
112	        }
113	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
114	    }
115	
116	    /**
117	     * The IANA timezone name derived from the given {@code locality} (a canonical
118	     * region) via the fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
119	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). Returns
120	     * {@code null} when the locality is not one of the known regions (for example
121	     * {@code "UNKNOWN"}).
122	     *
123	     * @return the IANA timezone name, or {@code null}
124	     */
125	    static String timezone(String locality) {
126	        return REGION_TIMEZONE.get(locality);
127	    }
128	
129	    /**
130	     * The region whose inclusive postcode range contains the given postcode, or
131	     * {@code null} when the postcode is absent, not a four-digit number, or in no
132	     * known range.
133	     */
134	    private static String regionForPostcode(String postcode) {
135	        if (postcode == null || !postcode.matches("\\d{4}")) {
136	            return null;
137	        }
138	        int value = Integer.parseInt(postcode);
139	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
140	            int[] range = entry.getValue();
141	            if (value >= range[0] && value <= range[1]) {
142	                return entry.getKey();
143	            }
144	        }
145	        return null;
146	    }
147	
148	    /**
149	     * Whether the given {@code postcode} is acceptable for the given {@code region}: an
150	     * absent postcode is always accepted, a present postcode must be exactly four
151	     * digits and, when the region has a known inclusive postcode range
152	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), fall within
153	     * it. A region with no known range (for example {@code "UNKNOWN"}) accepts any
154	     * four-digit postcode.
155	     *
156	     * @return {@code true} if the postcode is absent or valid for the region
157	     */
158	    static boolean postcodeMatchesRegion(String postcode, String region) {
159	        if (postcode == null) {
160	            return true;
161	        }
162	        if (!postcode.matches("\\d{4}")) {
163	            return false;
164	        }
165	        int[] range = REGION_POSTCODES.get(region);
166	        if (range == null) {
167	            return true;
168	        }
169	        int value = Integer.parseInt(postcode);
170	        return value >= range[0] && value <= range[1];
171	    }
172	
173	    /**
174	     * The owner's membership points, a non-negative score derived from its factors:
175	     * starting at 0, add 2 when an {@code email} is present, add 1 when
176	     * {@code namesakeCount} is 0, add 2 for a household of 3 or more (its
177	     * {@code householdSize}) and add 3 when the owner's tenure exceeds a year, measured as
178	     * the number of whole fiscal years elapsed from its {@code registrationDate} up to
179	     * {@code asOf} (the fiscal year starts on 1 July). Because a newly created owner has
180	     * zero elapsed fiscal years, it never earns the tenure points at creation.
181	     *
182	     * @return the membership points, 0 or more
183	     */
184	    static int membershipPoints(String email, Integer namesakeCount, Integer householdSize,
185	            LocalDate registrationDate, LocalDate asOf) {
186	        int points = 0;
187	        if (hasEmail(email)) {
188	            points += 2;
189	        }
190	        if (namesakeCount != null && namesakeCount == 0) {
191	            points += 1;
192	        }
193	        if (householdSize != null && householdSize >= 3) {
194	            points += 2;
195	        }
196	        if (tenureExceedsYear(registrationDate, asOf)) {
197	            points += 3;
198	        }
199	        return points;
200	    }
201	
202	    /**
203	     * The owner's membership level, a number from 1 to 4, mapped from its
204	     * {@link #membershipPoints(String, Integer, Integer, LocalDate, LocalDate) membership
205	     * points}: level 1 for 0-1 points, level 2 for 2-3, level 3 for 4-5 and level 4 for 6
206	     * or more.
207	     *
208	     * @return the membership level, from 1 to 4
209	     */
210	    static int membershipLevel(int points) {
211	        if (points <= 1) {
212	            return 1;
213	        }
214	        if (points <= 3) {
215	            return 2;
216	        }
217	        if (points <= 5) {
218	            return 3;
219	        }
220	        return 4;
221	    }
222	
223	    /**
224	     * The owner's membership level after applying its household level ceiling. The level
225	     * mapped from {@code points} (see {@link #membershipLevel(int)}) is returned unchanged
226	     * when {@code cap} is {@code null} (the owner joined no existing household), and
227	     * otherwise capped to at most {@code cap} — the ceiling assigned at creation, one above
228	     * the highest level then held by an existing household member — so a new owner can rise
229	     * to at most one level above its household.
230	     *
231	     * @return the capped membership level, from 1 to 4
232	     */
233	    static int membershipLevel(int points, Integer cap) {
234	        int level = membershipLevel(points);
235	        return cap == null ? level : Math.min(level, cap);
236	    }
237	
238	    /**
239	     * The owner's marketing segment, formatted {@code <TIER>_<AREA>}, one of
240	     * {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL}, {@code STANDARD_METRO} or
241	     * {@code STANDARD_REGIONAL}. TIER is {@code PREMIUM} when {@code membershipLevel} is 3
242	     * or more, otherwise {@code STANDARD}. AREA is {@code METRO} when {@code locality} is a
243	     * known region ({@code NSW}, {@code VIC} or {@code QLD}), otherwise {@code REGIONAL}.
244	     *
245	     * @return the owner's segment as {@code <TIER>_<AREA>}
246	     */
247	    static String ownerSegment(int membershipLevel, String locality) {
248	        String tier = membershipLevel >= 3 ? "PREMIUM" : "STANDARD";
249	        String area = REGION_TIMEZONE.containsKey(locality) ? "METRO" : "REGIONAL";
250	        return tier + "_" + area;
251	    }
252	
253	    /**
254	     * Whether the owner's tenure exceeds a year, i.e. at least one whole fiscal year has
255	     * elapsed from its {@code registrationDate} up to {@code asOf} (see
256	     * {@link #elapsedFiscalYears(LocalDate, LocalDate)}). This is the single tenure test
257	     * the tenure-driven membership derivations share, so they agree on exactly when an
258	     * owner has been a member for "over a year"; it is {@code false} whenever either date
259	     * is absent.
260	     */
261	    private static boolean tenureExceedsYear(LocalDate registrationDate, LocalDate asOf) {
262	        return registrationDate != null && asOf != null
263	            && elapsedFiscalYears(registrationDate, asOf) >= 1;
264	    }
265	
266	    /**
267	     * The number of whole fiscal years elapsed from {@code registrationDate} up to
268	     * {@code asOf}, i.e. the difference between the fiscal year that contains {@code asOf}
269	     * and the one that contains {@code registrationDate} (see {@link #fiscalYearOf(LocalDate)}).
270	     * Two dates in the same fiscal year yield {@code 0}, so an owner registered in the
271	     * current fiscal year has zero tenure until the next 1 July rollover.
272	     */
273	    static int elapsedFiscalYears(LocalDate registrationDate, LocalDate asOf) {
274	        return fiscalYearOf(asOf) - fiscalYearOf(registrationDate);
275	    }
276	
277	    /**
278	     * The fiscal year that contains the given date, as a four-digit calendar year. The
279	     * fiscal year runs from 1 July to 30 June and is labelled by the calendar year in
280	     * which it ends: a date from January to June falls in the fiscal year of its own
281	     * calendar year, while a date from July to December falls in the next calendar year's
282	     * fiscal year (e.g. {@code 2026-05-03 -> 2026} but {@code 2026-08-03 -> 2027}).
283	     */
284	    static int fiscalYearOf(LocalDate date) {
285	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
286	    }
287	
288	    /**
289	     * The owner's fiscal year, formatted {@code FY<YY>} where YY is the last two digits of
290	     * the fiscal year (see {@link #fiscalYearOf(LocalDate)}) that contains its
291	     * business-day-adjusted {@code registrationDate}, e.g. {@code FY27} for a registration
292	     * date of {@code 2026-08-03}. Returns {@code null} when no registration date is present.
293	     *
294	     * @return the fiscal year as {@code FY<YY>}, or {@code null}
295	     */
296	    static String fiscalYear(LocalDate registrationDate) {
297	        if (registrationDate == null) {
298	            return null;
299	        }
300	        return "FY" + fiscalYearSegment(registrationDate);
301	    }
302	
303	    /**
304	     * The two-digit fiscal-year segment for a registration date: the last two digits of the
305	     * fiscal year that contains it (see {@link #fiscalYearOf(LocalDate)}), zero-padded, e.g.
306	     * {@code "27"} for a registration date of {@code 2026-08-03}. This is the single
307	     * definition the fiscal-year-bearing identifiers share, so they agree on exactly which
308	     * two-digit year they carry.
309	     *
310	     * @return the two-digit fiscal-year segment
311	     */
312	    static String fiscalYearSegment(LocalDate registrationDate) {
313	        return String.format("%02d", fiscalYearOf(registrationDate) % 100);
314	    }
315	
316	    /**
317	     * The owner's salutation, formed as {@code title + ' ' + lastName} when a
318	     * {@code title} is present, or just the {@code lastName} when no title is supplied.
319	     * A {@code null} or blank title contributes nothing, yielding the bare last name.
320	     *
321	     * @return the composed salutation
322	     */
323	    static String salutation(String title, String lastName) {
324	        if (title == null || title.isBlank()) {
325	            return lastName;
326	        }
327	        return title + " " + lastName;
328	    }
329	
330	    /**
331	     * The owner's preferred contact channel: {@code "EMAIL"} when an {@code email}
332	     * is present, otherwise {@code "PHONE"}.
333	     *
334	     * @return {@code "EMAIL"} or {@code "PHONE"}
335	     */
336	    static String contactPreference(String email) {
337	        if (hasEmail(email)) {
338	            return "EMAIL";
339	        }
340	        return "PHONE";
341	    }
342	
343	    /**
344	     * Whether the owner has an email address on file, i.e. its {@code email} is present
345	     * and not blank. This is the single presence test the email-driven derivations share
346	     * (a membership-level factor and the {@link #contactPreference(String) contact
347	     * preference}), so they agree on exactly what counts as "has an email".
348	     */
349	    private static boolean hasEmail(String email) {
350	        return email != null && !email.isBlank();
351	    }
352	
353	    /**
354	     * The Luhn check digit (0-9) computed over the decimal digits contained in the
355	     * given {@code value}, processed right-to-left with every second digit doubled (and
356	     * reduced by 9 when the double exceeds 9). Non-digit characters are ignored, and an
357	     * absent or digit-free value yields {@code 0}.
358	     *
359	     * @return the Luhn check digit, from 0 to 9
360	     */
361	    static int checkDigit(String value) {
362	        int sum = 0;
363	        boolean doubleDigit = true;
364	        for (int i = (value == null ? 0 : value.length()) - 1; i >= 0; i--) {
365	            char c = value.charAt(i);
366	            if (c < '0' || c > '9') {
367	                continue;
368	            }
369	            int d = c - '0';
370	            if (doubleDigit) {
371	                d *= 2;
372	                if (d > 9) {
373	                    d -= 9;
374	                }
375	            }
376	            sum += d;
377	            doubleDigit = !doubleDigit;
378	        }
379	        return (10 - (sum % 10)) % 10;
380	    }
381	
382	    /**
383	     * The owner's age band, derived from its {@code birthDate} measured against its
384	     * {@code registrationDate}: {@code "MINOR"} when the owner is under 18 on the
385	     * registration date, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or
386	     * over. The age is the number of whole years between the two dates. Returns
387	     * {@code null} when either date is absent, so no band is reported for an owner
388	     * without a supplied birth date.
389	     *
390	     * @return {@code "MINOR"}, {@code "ADULT"}, {@code "SENIOR"}, or {@code null}
391	     */
392	    static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
393	        if (birthDate == null || registrationDate == null) {
394	            return null;
395	        }
396	        int age = Period.between(birthDate, registrationDate).getYears();
397	        if (age < 18) {
398	            return "MINOR";
399	        }
400	        if (age < 65) {
401	            return "ADULT";
402	        }
403	        return "SENIOR";
404	    }
405	
406	    /**
407	     * The single derived key used for duplicate detection: the lower-case hexadecimal
408	     * SHA-256 digest of {@code normalizedTelephone + '|' + lowerEmail + '|' +
409	     * soundex(lastName)}. The telephone is the owner's stored (E.164-normalised)
410	     * telephone (or the empty string when absent), the email is the stored (lower-cased)
411	     * email or the empty string when absent, and the last-name component is the
412	     * {@link #soundex(String) Soundex code} of the owner's last name. Because the
413	     * telephone is part of the key, two owners sharing a last name and postcode but with
414	     * different telephones have different keys.
415	     *
416	     * @return the owner's identity key, a 64-character lower-case hex string
417	     */
418	    static String identityKey(String telephone, String email, String lastName) {
419	        String tel = telephone == null ? "" : telephone;
420	        String mail = email == null ? "" : email.toLowerCase();
421	        return sha256Hex(tel + "|" + mail + "|" + soundex(lastName));
422	    }
423	
424	    /**
425	     * The American Soundex code of the given name: its first letter followed by three
426	     * digits derived from the remaining consonants ({@code b,f,p,v -> 1};
427	     * {@code c,g,j,k,q,s,x,z -> 2}; {@code d,t -> 3}; {@code l -> 4}; {@code m,n -> 5};
428	     * {@code r -> 6}), where adjacent letters mapping to the same digit (including when
429	     * separated only by {@code h} or {@code w}) are coded once, vowels ({@code a,e,i,o,u},
430	     * and {@code y}) separate otherwise-identical digits, and the result is zero-padded or
431	     * truncated to exactly four characters. Non-letters are ignored; an absent or
432	     * letter-free value yields the empty string.
433	     *
434	     * @param value the name to encode (may be {@code null})
435	     * @return the four-character Soundex code, or the empty string
436	     */
437	    static String soundex(String value) {
438	        if (value == null) {
439	            return "";
440	        }
441	        StringBuilder letters = new StringBuilder();
442	        for (char c : value.toUpperCase().toCharArray()) {
443	            if (c >= 'A' && c <= 'Z') {
444	                letters.append(c);
445	            }
446	        }
447	        if (letters.length() == 0) {
448	            return "";
449	        }
450	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
451	        char previousDigit = soundexDigit(letters.charAt(0));
452	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
453	            char letter = letters.charAt(i);
454	            char digit = soundexDigit(letter);
455	            if (digit != '0' && digit != previousDigit) {
456	                code.append(digit);
457	            }
458	            if (letter != 'H' && letter != 'W') {
459	                previousDigit = digit;
460	            }
461	        }
462	        while (code.length() < 4) {
463	            code.append('0');
464	        }
465	        return code.toString();
466	    }
467	
468	    /**
469	     * The Soundex digit for a single upper-case letter, or {@code '0'} for a letter that
470	     * carries no Soundex digit (the vowels {@code a,e,i,o,u}, and {@code y,h,w}).
471	     */
472	    private static char soundexDigit(char c) {
473	        return switch (c) {
474	            case 'B', 'F', 'P', 'V' -> '1';
475	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
476	            case 'D', 'T' -> '3';
477	            case 'L' -> '4';
478	            case 'M', 'N' -> '5';
479	            case 'R' -> '6';
480	            default -> '0';
481	        };
482	    }
483	
484	    /**
485	     * The owner's unified member id, formatted {@code <REGION><FY><HASH8><CHK>}: {@code region}
486	     * is the owner's canonical region (see {@link #region(String, String)}), FY is the
487	     * two-digit {@link #fiscalYearSegment(LocalDate) fiscal-year segment} of its
488	     * {@code registrationDate}, HASH8 is the {@link #hash8(String, String) HASH8} of its
489	     * telephone and last name, and CHK is a single {@link #checkDigit(String) Luhn check
490	     * digit} computed over the decimal digits of {@code <REGION><FY><HASH8>}
491	     * (e.g. {@code NSW279F86D0817}). This unifies the former customer code and membership
492	     * number into one identifier.
493	     *
494	     * @return the member id
495	     */
496	    static String memberId(String region, String telephone, String lastName,
497	            LocalDate registrationDate) {
498	        String base = region + fiscalYearSegment(registrationDate) + hash8(telephone, lastName);
499	        return base + checkDigit(base);
500	    }
501	
502	    /**
503	     * The HASH8 component of the region-and-hash identity: the first eight upper-case
504	     * hexadecimal characters of the SHA-256 digest of the owner's normalised
505	     * {@code telephone} concatenated with its {@code lastName} (e.g. {@code 9F86D081}).
506	     * Held as its own derivation so the identity's hash component has a single definition
507	     * rather than being spelled out at each identifier that embeds it.
508	     *
509	     * @return the eight upper-case hexadecimal HASH8 characters
510	     */
511	    static String hash8(String telephone, String lastName) {
512	        return sha256Hex(telephone + lastName).substring(0, 8).toUpperCase();
513	    }
514	
515	    /**
516	     * The stable identifier for the household an owner belongs to, derived
517	     * deterministically from its {@code normalizedLastName} and {@code postcode} so that
518	     * every owner sharing a last name and postcode resolves to the same value. It is the
519	     * first twelve lower-case hexadecimal characters of the SHA-256 digest of
520	     * {@code normalizedLastName + '|' + postcode} (an absent postcode contributes the
521	     * empty string).
522	     *
523	     * @return the household identifier
524	     */
525	    static String householdId(String normalizedLastName, String postcode) {
526	        String pc = postcode == null ? "" : postcode;
527	        return sha256Hex(normalizedLastName + "|" + pc).substring(0, 12);
528	    }
529	
530	    /**
531	     * Reduce an address to its canonical stored form: trim and collapse runs of
532	     * whitespace to a single space, upper-case, and expand common abbreviations
533	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}) whenever
534	     * they appear as whole words. The result is what is stored, returned and used
535	     * for every household comparison; it is idempotent, so re-normalising an
536	     * already-normalised address leaves it unchanged.
537	     *
538	     * @param value the raw address (may be {@code null})
539	     * @return the normalised address, or the empty string if {@code value} is
540	     *         {@code null} or blank
541	     */
542	    static String normalizeAddress(String value) {
543	        String collapsed = collapseWhitespace(value).toUpperCase();
544	        if (collapsed.isEmpty()) {
545	            return "";
546	        }
547	        String[] tokens = collapsed.split(" ");
548	        for (int i = 0; i < tokens.length; i++) {
549	            tokens[i] = switch (tokens[i]) {
550	                case "ST" -> "STREET";
551	                case "RD" -> "ROAD";
552	                case "AVE" -> "AVENUE";
553	                default -> tokens[i];
554	            };
555	        }
556	        return String.join(" ", tokens);
557	    }
558	
559	    /**
560	     * Trim the given value and collapse every internal run of whitespace to a single
561	     * space, treating an absent value as empty. This is the single whitespace
562	     * normalisation the name and address normalisers share, so they agree on what
563	     * counts as insignificant whitespace; each then applies its own casing (and, for
564	     * addresses, whole-word abbreviation expansion).
565	     *
566	     * @param value the raw value (may be {@code null})
567	     * @return the trimmed, whitespace-collapsed value, or the empty string when
568	     *         {@code value} is {@code null}
569	     */
570	    static String collapseWhitespace(String value) {
571	        if (value == null) {
572	            return "";
573	        }
574	        return value.trim().replaceAll("\\s+", " ");
575	    }
576	
577	    /**
578	     * The SHA-256 digest of the UTF-8 bytes of the given value, as a lower-case
579	     * hexadecimal string. Callers take the prefix and case they need.
580	     */
581	    static String sha256Hex(String value) {
582	        try {
583	            byte[] digest = MessageDigest.getInstance("SHA-256")
584	                .digest(value.getBytes(StandardCharsets.UTF_8));
585	            StringBuilder hex = new StringBuilder(digest.length * 2);
586	            for (byte b : digest) {
587	                hex.append(String.format("%02x", b));
588	            }
589	            return hex.toString();
590	        } catch (NoSuchAlgorithmException e) {
591	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
592	        }
593	    }
594	}
