415	    /**
416	     * The household level ceiling assigned to this owner at creation: one above the highest
417	     * {@link #getMembershipLevel() membership level} then held by an existing member of its
418	     * household, or {@code null} when the owner joined no existing household (so no ceiling
419	     * applies). Persisted, and used by {@link #getMembershipLevel()} to cap the reported
420	     * level.
421	     *
422	     * @return the household level ceiling, or {@code null} when uncapped
423	     */
424	    public Integer getMembershipLevelCap() {
425	        return this.membershipLevelCap;
426	    }
427	
428	    public void setMembershipLevelCap(Integer membershipLevelCap) {
429	        this.membershipLevelCap = membershipLevelCap;
430	    }
431	
432	    public Boolean getDeleted() {
433	        return this.deleted;
434	    }
435	
436	    public void setDeleted(Boolean deleted) {
437	        this.deleted = deleted;
438	    }
439	
440	    /**
441	     * The derived key used for duplicate detection: the SHA-256 hex digest over this
442	     * owner's normalised telephone, lower-cased email and the {@link #soundex(String)
443	     * Soundex} of its last name. Two owners are duplicates exactly when their whole
444	     * identity keys are equal, so because the telephone is part of the key, members of
445	     * the same household with different telephones have different keys. Derived (not
446	     * persisted); recomputed each call. See
447	     * {@link OwnerDerivations#identityKey(String, String, String)} for the exact format.
448	     *
449	     * @return the owner's identity key
450	     */
451	    @Transient
452	    public String getIdentityKey() {
453	        return OwnerDerivations.identityKey(this.telephone, this.email, this.getLastName());
454	    }
455	
456	    /**
457	     * The American Soundex code of the given name. This is the last-name comparison used
458	     * by both the identity key and the soft-match duplicate check; see
459	     * {@link OwnerDerivations#soundex(String)} for the exact algorithm.
460	     *
461	     * @param value the name to encode (may be {@code null})
462	     * @return the four-character Soundex code, or the empty string
463	     */
464	    public static String soundex(String value) {
465	        return OwnerDerivations.soundex(value);
466	    }
467	
468	    /**
469	     * Compute the unified member id to assign to this owner at creation, formatted
470	     * {@code <REGION><FY><HASH8><CHK>} from the owner's (already normalised) fields and
471	     * registration date. This is the value stored in {@link #getMemberId()}; see
472	     * {@link OwnerDerivations#memberId(String, String, String, LocalDate)} for the exact
473	     * format.
474	     *
475	     * @return the member id to assign
476	     */
477	    public String computeMemberId() {
478	        return OwnerDerivations.memberId(regionForOwner(), this.telephone, this.getLastName(),
479	            this.registrationDate);
480	    }
481	
482	    /**
483	     * Compute the stable household identifier for this owner, derived deterministically
484	     * from its last name and postcode so every owner sharing a last name and postcode
485	     * resolves to the same value. This is the value stored in {@link #getHouseholdId()};
486	     * see {@link OwnerDerivations#householdId(String, String)} for the exact derivation.
487	     *
488	     * @return the household identifier
489	     */
490	    public String computeHouseholdId() {
491	        return OwnerDerivations.householdId(normalize(this.getLastName()), this.postcode);
492	    }
493	
494	    /**
495	     * Whether this owner belongs to the same household as {@code other}: that is, they
496	     * share the same last name and postcode. The last name is compared
497	     * case-insensitively with runs of whitespace collapsed to a single space (and
498	     * surrounding whitespace trimmed); the postcode is compared for exact equality (two
499	     * absent postcodes count as equal). Owners in the same household resolve to the same
500	     * {@link #computeHouseholdId() household identifier}.
501	     *
502	     * @param other the owner to compare against
503	     * @return {@code true} if both owners share a household
504	     */
505	    public boolean sameHouseholdAs(Owner other) {
506	        return normalize(this.getLastName()).equals(normalize(other.getLastName()))
507	            && Objects.equals(this.postcode, other.postcode);
508	    }
509	
510	    /**
511	     * Normalise a value for case-insensitive, whitespace-insensitive comparison:
512	     * trim, collapse internal runs of whitespace to a single space and lower-case.
513	     */
514	    private static String normalize(String value) {
515	        return OwnerDerivations.collapseWhitespace(value).toLowerCase();
516	    }
517	
518	    /**
519	     * Reduce an address to its canonical stored form. This is the value stored,
520	     * returned and used for every household comparison; see
521	     * {@link OwnerDerivations#normalizeAddress(String)} for the exact normalisation.
522	     *
523	     * @param value the raw address (may be {@code null})
524	     * @return the normalised address, or the empty string if {@code value} is
525	     *         {@code null} or blank
526	     */
527	    public static String normalizeAddress(String value) {
528	        return OwnerDerivations.normalizeAddress(value);
529	    }
530	
531	    protected Set<Pet> getPetsInternal() {
532	        if (this.pets == null) {
533	            this.pets = new HashSet<>();
534	        }
535	        return this.pets;
536	    }
537	
538	    protected void setPetsInternal(Set<Pet> pets) {
539	        this.pets = pets;
540	    }
541	
542	    public List<Pet> getPets() {
543	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
544	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
545	        return Collections.unmodifiableList(sortedPets);
546	    }
547	
548	    public void setPets(List<Pet> pets) {
549	        this.pets = new HashSet<>(pets);
550	    }
551	
552	    public void addPet(Pet pet) {
553	        getPetsInternal().add(pet);
554	        pet.setOwner(this);
555	    }
556	
557	    /**
558	     * Return the Pet with the given name, or null if none found for this Owner.
559	     *
560	     * @param name to test
561	     * @return true if pet name is already in use
562	     */
563	    public Pet getPet(String name) {
564	        return getPet(name, false);
565	    }
566	
567	    /**
568	     * Return the Pet with the given name, or null if none found for this Owner.
569	     *
570	     * @param name to test
571	     * @return true if pet name is already in use
572	     */
573	    public Pet getPet(String name, boolean ignoreNew) {
574	        name = name.toLowerCase();
575	        for (Pet pet : getPetsInternal()) {
576	            if (!ignoreNew || !pet.isNew()) {
577	                String compName = pet.getName();
578	                compName = compName.toLowerCase();
579	                if (compName.equals(name)) {
580	                    return pet;
581	                }
582	            }
583	        }
584	        return null;
585	    }
586	
587	    public Pet getPet(Integer petId) {
588	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
589	    }
590	
591	    @Override
592	    public String toString() {
593	        return new ToStringCreator(this)
594	
595	            .append("id", this.getId())
596	            .append("new", this.isNew())
597	            .append("lastName", this.getLastName())
598	            .append("firstName", this.getFirstName())
599	            .append("address", this.address)
600	            .append("city", this.city)
601	            .append("telephone", this.telephone)
602	            .toString();
603	    }
604	}
