380	     */
381	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
382	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
383	
384	    /**
385	     * Whether the given (already lower-cased) email address belongs to a disposable
386	     * mailbox domain on the blocklist. The domain is the part after the final
387	     * {@code '@'}; an address without one is treated as having no blocked domain.
388	     *
389	     * @param email the owner's normalised (lower-cased) email address
390	     * @return {@code true} if the email's domain is on the disposable-domain blocklist
391	     */
392	    private static boolean emailDomainIsBlocked(String email) {
393	        int at = email.lastIndexOf('@');
394	        if (at < 0) {
395	            return false;
396	        }
397	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
398	    }
