401	     * The fixed list of public holidays on which the clinic is closed. A registration
402	     * date that lands on one of these dates is treated the same as a weekend and rolled
403	     * forward past it (see {@link #rollToBusinessDay(LocalDate)}).
404	     */
405	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
406	        LocalDate.of(2026, 1, 1),
407	        LocalDate.of(2026, 1, 26),
408	        LocalDate.of(2026, 4, 25),
409	        LocalDate.of(2026, 12, 25),
